  function hut2(isl, dx, dy, spec) {
    return { kind: "building", dx, dy, fw: 6, fd: 4, hgt: 3, style: "town", roofType: "gable", showName: true, ...spec };
  }
  var planks = (x0, x1, y0, y1) => ({ op: "rect", x0, x1, y0, y1, tile: T2.BRIDGE, onlyWater: true });
  function span(isl, a, b, rx, ry) {
    const hw = isl.w / 2, hh = isl.h / 2;
    const ax = a[0] * hw, ay = a[1] * hh, bx = b[0] * hw, by = b[1] * hh;
    const dx = bx - ax, dy = by - ay, d = Math.hypot(dx, dy);
    const ux = dx / d, uy = dy / d;
    const r4 = 1 / Math.hypot(ux / (rx * hw), uy / (ry * hh));
    const s = r4 - 4;
    return { op: "path", points: [[(ax + ux * s) / hw, (ay + uy * s) / hh], [(bx - ux * s) / hw, (by - uy * s) / hh]], width: 3, tile: T2.BRIDGE };
  }
