      game.emit("shipBought", type);
      game.audio?.sfx("coin");
      finish2(r4, "NEW SHIP", `Your new ${d.name}, the ${r4.ship.name}, is launched and made fast alongside ${pierName(dock, island)}: step aboard, and press E at her ${d.oarsOnly ? "oars" : "wheel"} to take her out.`);
