            const x = w.wx(p.x + Math.cos(a) * r4), y = p.y + Math.sin(a) * r4;
            if (!w.isLiquid(x, y) || w.isOverlay(x, y)) continue;
            if ((game.seaDepth ? game.seaDepth(x, y) : 9) < need) continue;
            if (ok && !ok(x, y)) continue;
            return { x, y, a };
