        const stand = { ...def, hostile: true, dialogue: null, marker: null, when: null, once: false };
        const a = makeNPC(stand, s.x, s.y);
        a.npcId = null;
        a.def = { ...stand, id: null };
        a.bountyValue = 0;
        a.infamy = false;
        a.reward = 0;
