        const L3 = d.length;
        const sea = C3.waterNear(4, Math.round(L3 * 0.6 + 26), Math.round(L3 * 0.6 + 140), (x, y) => w.sailable(x, y) && w.sd(x, y) < -4 - L3 * 0.35);
        if (!sea) return "No open water near you for her \u2014 go down to the sea.";
