  function drawWhale(g, env2, marked) {
    const t = env2?.time || 0;
    const TAU30 = Math.PI * 2;
    g.save();
    g.translate(0, Math.sin(t * 0.7) * 0.12);
    g.fillStyle = "rgba(255,255,255,0.28)";
    g.beginPath();
    g.ellipse(0, 0.9, 11.5, 2.4, 0, 0, TAU30);
    g.fill();
    g.fillStyle = "#4e6177";
    g.beginPath();
    g.moveTo(9, -0.8);
    g.lineTo(12.6, -2.8);
    g.lineTo(11.7, -0.8);
    g.lineTo(12.6, 1.1);
    g.closePath();
    g.fill();
    g.fillStyle = "#5d7389";
    g.beginPath();
    g.ellipse(0, -1.4, 10, 3.4, 0, 0, TAU30);
    g.fill();
    g.fillStyle = "#d7e1ea";
    g.beginPath();
    g.ellipse(-1, 0.6, 8.5, 1.5, 0, 0, Math.PI);
    g.fill();
    g.strokeStyle = "rgba(255,235,238,0.75)";
    g.lineWidth = 0.18;
    for (let k = 0; k < 5; k++) {
      g.beginPath();
      g.moveTo(-9.6 + k * 0.35, -3.6 + k * 0.4);
      g.lineTo(-8.2 + k * 0.3, -2.2 + k * 0.5);
      g.stroke();
    }
    g.fillStyle = "#fafafa";
    g.beginPath();
    g.arc(-6.6, -1.8, 0.45, 0, TAU30);
    g.fill();
    g.fillStyle = "#1a1a1a";
    g.beginPath();
    g.arc(-6.7, -1.8, 0.24, 0, TAU30);
    g.fill();
    if (marked) {
      g.fillStyle = "#fafafa";
      g.beginPath();
      g.arc(-8.2, -3.1, 0.8, 0, TAU30);
      g.fill();
      g.strokeStyle = "#fafafa";
      g.lineWidth = 0.25;
      g.beginPath();
      g.moveTo(-9.3, -2);
      g.lineTo(-7.1, -4.2);
      g.moveTo(-9.3, -4.2);
      g.lineTo(-7.1, -2);
      g.stroke();
      g.fillStyle = "#1a1a1a";
      g.beginPath();
      g.arc(-8.45, -3.2, 0.16, 0, TAU30);
      g.arc(-7.95, -3.2, 0.16, 0, TAU30);
      g.fill();
    }
    const ph = t % 14;
    if (ph < 1.6) {
      const h2 = Math.sin(ph / 1.6 * Math.PI) * 3.2;
      g.fillStyle = "rgba(225,245,254,0.8)";
      g.beginPath();
      g.ellipse(-3, -4.8 - h2 / 2, 0.5 + h2 * 0.2, h2 / 2 + 0.2, 0, 0, TAU30);
      g.fill();
    }
    g.font = "bold 0.5px Nunito, sans-serif";
    g.textAlign = "center";
    g.fillStyle = "#fff";
    g.strokeStyle = "#000";
    g.lineWidth = 0.08;
    g.strokeText("Laboon", 0, -5.6);
    g.fillText("Laboon", 0, -5.6);
    g.restore();
  }
