      name: "Kokoro",
      title: "Stationmaster of Shift Station",
      island: "water_7",
      ai: "idle",
      look: { hair: "curly", hairColor: "#fafafa", top: "#7b1fa2", bottom: "#4a148c", skin: "#f1c9a0", bulk: 1.5 },
