      invulnerable: true,
      style: "brawler",
      moves: ["p2_strong_right", "brawl_tackle"],
      look: { hair: "pompadour", hairColor: "#29b6f6", top: "#e53935", bottom: "#1565c0", skin: "#f1c9a0", hand: "#b0bec5", bulk: 1.4, openShirt: true },
      bulk: 1.4,
      level: 45,
