      when: (c) => !c.flags.nw_toysFreed,
      dialogue: (ctx) => ({
        start: "a",
        nodes: {
          a: {
            text: () => active4(ctx, "nw_sop", "soldier") ? '"(A tin soldier balancing on one leg salutes you with a toy sword.) Leo sent you? Then listen well. Every toy in Dressrosa was once a person. Sugar of the Donquixote Family touched them, and the world forgot they ever existed."' : '"(A one-legged toy soldier stands guard over the Colosseum, silent.) ...Move along, friend. A toy has nothing to say."',
            choices: [{ text: "Go on.", if: () => active4(ctx, "nw_sop", "soldier"), next: "plan" }, { text: "Leave.", end: true }]
          },
          plan: {
            text: `"Operation SOP \u2014 Sugar Ottamage Panic. Knock Sugar out and her curse breaks. Every toy becomes human again, every memory returns. She hides in the Toy House at the foot of the King's Plateau. Beware her touch \u2014 one tap and you become a toy yourself."`,
            choices: [{ text: "To the Toy House.", do: (c) => c.stage("nw_sop", "sugar"), end: true }]
          }
        }
      })
