      at: { spot: "oden_castle", ox: 4 },
      faction: "neutral",
      look: { hair: "long", hairColor: "#eceff1", top: "#fafafa", bottom: "#ef6c00", hat: "horns", hatColor: "#e53935", skin: "#f1c9a0", eyeColor: "#ff8f00" },
      level: 92,
