      at: { town: "labophase", building: "Vegapunk's Laboratory" },
      look: { hair: "long", hairColor: "#8d6e63", top: "#fafafa", bottom: "#fafafa", coat: "#fafafa", skin: "#f1c9a0", goggles: true },
